  tools.mcp__codex_apps__github_fetch_issue({repository_full_name:"PJensen/JSHack", issue_number})
));
const out = rs.map((r,i) => {
  const s = r?.structuredContent ?? {};
  const issue = s.issue ?? s;
  return {
    number: nums[i],
    title: issue.title,
    labels: issue.labels,
    body: typeof issue.body === "string" ? issue.body.slice(0,1800).replace(/\s+/g," ") : issue.body,
    url: issue.html_url ?? issue.url ?? issue.display_url
  };
});
text(JSON.stringify(out));

const comment = `## disposition

Closing this issue as a standalone broad initiative.

The project will capture skills incrementally during normal feature work instead:

- \`AGENTS.md\` now requires recording proven tools, workflows, authoring paths, verification commands, invariants, fixtures, and failure modes as they are discovered.
- The smallest relevant \`.agents/skills/\` guide should be updated as part of the feature or its immediate follow-up.
- Broad skills coverage is not a prerequisite for gameplay work.
- Speculative or repository-wide skill rewrites are deferred until repeated workflows provide evidence for them.

This preserves the goal of improving LUNA's starting position while keeping the documentation grounded in real implementation experience.`;
